def mark_existing_owner_badges(apps, schema_editor):
    Badge = apps.get_model("blog", "CommentBadge")
    Assignment = apps.get_model("blog", "CommentBadgeAssignment")
    User = apps.get_model("auth", "User")
    for config_id in Badge.objects.values_list("config_id", flat=True).distinct():
        badge = Badge.objects.filter(
            config_id=config_id,
            name__in=("博主", "Blogger", "Owner", "Author"),
        ).order_by("id").first()
        if badge:
            Badge.objects.filter(pk=badge.pk).update(is_owner_badge=True)
            Assignment.objects.bulk_create(
                [Assignment(user_id=user_id, badge_id=badge.pk) for user_id in User.objects.filter(is_superuser=True, is_active=True).values_list("pk", flat=True)],
                ignore_conflicts=True,
            )


def add_owner_badge_translations(apps, schema_editor):
    Badge = apps.get_model("blog", "CommentBadge")
    Translation = apps.get_model("blog", "CommentBadgeTranslation")
    names = {
        "en": "Blogger",
        "es": "Autor",
        "fr": "Auteur",
        "ja": "ブログ管理者",
        "zh-hans": "博主",
        "zh-hk": "博主",
        "zh-tw": "站長",
    }
    Translation.objects.bulk_create(
        [
            Translation(badge_id=badge_id, language_code=language, name=name)
            for badge_id in Badge.objects.filter(is_owner_badge=True).values_list("pk", flat=True)
            for language, name in names.items()
        ],
        ignore_conflicts=True,
    )


